import{_ as t,o as n,c as a,a6 as i}from"./chunks/framework.BJFjZBwW.js";const o="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-ip.DC3zqH6F.png",s="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-binding.69HLVtYS.png",l="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-binding2.ClDkBiwy.png",r="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-binding3.DGPnkQOU.png",p="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-binding4.BYzd8Czq.png",h="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-binding5.BRVRdKZG.png",d="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-binding6.BTyreAKl.png",c="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-jinja.4_IJUGls.png",g="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-things.A995UmLv.png",u="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-things2.BPtTKD-z.png",m="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-things3.CaqwmvJ5.png",T="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-things4.CqqnVHiH.png",b="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt-things5.BBQNIXi4.png",q="/dev/assets/OpenMQTTGateway-OpenHAB-Theengs-mqtt.C0_xbIYl.png",v=JSON.parse('{"title":"Integrate OPENHAB 3/4","description":"","frontmatter":{},"headers":[],"relativePath":"integrate/openhab3.md","filePath":"integrate/openhab3.md","lastUpdated":1737836062000}'),f={name:"integrate/openhab3.md"};function O(y,e,B,w,A,k){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="integrate-openhab-3-4" tabindex="-1">Integrate OPENHAB 3/4 <a class="header-anchor" href="#integrate-openhab-3-4" aria-label="Permalink to &quot;Integrate OPENHAB 3/4&quot;">​</a></h1><p>This tutorial will show how to integrate the BLE gateway to OpenHAB 3 or 4 leveraging the auto discovery functionality. After this tutorial, you should see your Bluetooth Low Energy devices in OpenHAB without any file based manual configuration.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>OpenHAB 3.3 or higher</li><li>MQTT broker installed with or without authentication</li><li>A location defined in the &quot;Model&quot; section under &quot;Settings&quot;</li></ul><h2 id="ip-address-if-your-broker-is-installed-on-the-same-server-as-openhab" tabindex="-1">IP address (if your broker is installed on the same server as OpenHAB) <a class="header-anchor" href="#ip-address-if-your-broker-is-installed-on-the-same-server-as-openhab" aria-label="Permalink to &quot;IP address (if your broker is installed on the same server as OpenHAB)&quot;">​</a></h2><p>The goal is to disable the IPv6 address of the broker server, so that the gateway can connect through IPv4.</p><ol><li>From the Administration click on Settings</li><li>Click on Network Settings</li><li>Click on Show Advanced</li><li>Disable IPv6</li><li>Click on Save</li></ol><p><img src="'+o+'" alt="OpenHAB integration"></p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>If the broker is installed on another server you will also need to configure it with an IPv4 address.</p></div><h2 id="install-the-mqtt-binding" tabindex="-1">Install the MQTT binding <a class="header-anchor" href="#install-the-mqtt-binding" aria-label="Permalink to &quot;Install the MQTT binding&quot;">​</a></h2><ol><li>From the Administration click on Settings</li><li>Click on Bindings</li><li>Install the MQTT binding (you can search at the bottom right)</li></ol><p><img src="'+s+'" alt="OpenHAB integration"></p><ol start="4"><li>Once installed click on Things under Settings</li><li>Click on the + at the bottom right</li><li>Click on MQTT Binding</li></ol><p><img src="'+l+'" alt="OpenHAB integration"></p><ol start="7"><li>Click on MQTT broker</li></ol><p><img src="'+r+'" alt="OpenHAB integration"></p><ol start="8"><li>Enter for the &quot;Broker Hostname/IP&quot; field, the IP address of your broker, if it is installed on the same server you can enter <code>localhost</code></li></ol><p><img src="'+p+'" alt="OpenHAB integration"></p><ol start="9"><li>Click on &quot;Show Advanced&quot; if your broker has authentication activated, if not you can go to step 11</li><li>Enter the broker credentials: username and password</li></ol><p><img src="'+h+'" alt="OpenHAB integration"></p><ol start="11"><li>Click on Create Thing at the bottom, you should see your MQTT Broker in the Things list with the status &quot;online&quot;</li></ol><p><img src="'+d+'" alt="OpenHAB integration"></p><p>Bravo👏, second step done! Now let&#39;s add the Jinja transformation service.</p><h2 id="install-jinja-and-jsonpath-transformations" tabindex="-1">Install Jinja and JSONPath Transformations <a class="header-anchor" href="#install-jinja-and-jsonpath-transformations" aria-label="Permalink to &quot;Install Jinja and JSONPath Transformations&quot;">​</a></h2><ol><li>From the Administration click on Settings</li><li>Click on Bindings</li><li>Install Jinja Transformation (you can search at the bottom right)</li><li>Install JSONPath Transformation</li></ol><p><img src="'+c+'" alt="OpenHAB integration"></p><p>Second step done!</p><h2 id="upload-openmqttgateway-to-an-esp32" tabindex="-1">Upload OpenMQTTGateway to an ESP32 <a class="header-anchor" href="#upload-openmqttgateway-to-an-esp32" aria-label="Permalink to &quot;Upload OpenMQTTGateway to an ESP32&quot;">​</a></h2><p><a href="./../upload/web-install.html">Upload OpenMQTTGateway from the web</a> by selecting the environment corresponding to your need.</p><p>Or use another upload method from the Upload section.</p><h2 id="configure-openmqttgateway-from-the-web-portal" tabindex="-1">Configure OpenMQTTGateway from the web portal <a class="header-anchor" href="#configure-openmqttgateway-from-the-web-portal" aria-label="Permalink to &quot;Configure OpenMQTTGateway from the web portal&quot;">​</a></h2><p><a href="./../upload/portal.html">Wifi and MQTT configuration</a></p><p>Or use another upload method from the Upload section that requires credentials before the build.</p><p>You should see the gateway connected to your broker by checking with an MQTT client like MQTT Explorer.</p><h2 id="adding-the-things" tabindex="-1">Adding the things <a class="header-anchor" href="#adding-the-things" aria-label="Permalink to &quot;Adding the things&quot;">​</a></h2><ol><li>From the Administration click on &quot;Things&quot; under &quot;Settings&quot;, you should see a number in the INBOX button</li></ol><p><img src="'+g+'" alt="OpenHAB integration"></p><ol start="2"><li>Click on INBOX, you should see your BLE devices and the gateway</li></ol><p><img src="'+u+'" alt="OpenHAB integration"></p><ol start="3"><li>Click on a device, a pop up &quot;Add as Thing&quot; should appear</li><li>Rename it if you need, and click OK, repeat for each Thing discovered. The devices should appears as online progressively.</li></ol><p><img src="'+m+'" alt="OpenHAB integration"></p><ol start="5"><li>Click on Model</li><li>Select the location of where you want to create the Equipment</li><li>Click on &quot;Create Equipment from Thing&quot;</li><li>Click on Thing</li><li>Select a Thing</li><li>Rename your Equipment if you need</li><li>Select the Channels</li></ol><p><img src="'+T+'" alt="OpenHAB integration"></p><ol start="12"><li>Click on &quot;Add to Model&quot;</li><li>Go to Model, if you unfold your location and Equipment you should be able to see values</li></ol><p><img src="'+b+'" alt="OpenHAB integration"></p><p>Congratulation🎉! You were able to get data from your BLE sensors into OpenHAB. You can now add the others and use the data to build pages, leverage rules and enjoy all the function of your Home Automation controller with BLE devices.</p><p><img src="'+q+'" alt="OpenHAB integration"></p>',47)])])}const H=t(f,[["render",O]]);export{v as __pageData,H as default};
